/**
 * generate_bundle.js
 * ==================
 * Merges all Antigravity context files into a single context_bundle.md
 * for upload to Claude Project.
 *
 * Run: node generate_bundle.js
 * Location: C:\Users\nimro\.gemini\antigravity\scratch\antigravity-context\
 */

const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const OUTPUT = path.join(ROOT, 'context_bundle.md');
const NOW = new Date().toISOString().slice(0, 10);

// Sections to merge in order — [title, source file, section number]
const SECTIONS = [
  {
    num: 1,
    title: 'WHO NIMROD IS & BUSINESS GOALS',
    source: 'master_workspace_profile.md',
    note: 'master_workspace_profile.md'
  },
  {
    num: 2,
    title: 'POWER COMMANDS (SHORTHAND TRIGGERS)',
    source: 'power_commands.md',
    note: 'power_commands.md'
  },
  {
    num: 3,
    title: 'AUTOMATION SCRIPTS',
    source: 'automations_handbook.md',
    note: 'automations_handbook.md'
  },
  {
    num: 4,
    title: 'ACTIVE PROJECTS',
    source: 'projects_inventory.md',
    note: 'projects_inventory.md'
  },
  {
    num: 5,
    title: 'PC FILE PATH MAP',
    source: 'pc_path_map.md',
    note: 'pc_path_map.md'
  },
  {
    num: 6,
    title: 'SUBAGENTS',
    source: 'agents_handbook.md',
    note: 'agents_handbook.md'
  },
  {
    num: 7,
    title: 'CURRENT SESSION STATUS',
    source: 'active-session/checklist.md',
    extra: 'active-session/walkthrough.md',
    note: 'active-session/checklist.md & walkthrough.md'
  },
  {
    num: 8,
    title: 'MCP SERVERS',
    source: 'antigravity-system/mcp_servers.md',
    note: 'antigravity-system/mcp_servers.md'
  },
  {
    num: 9,
    title: 'PLUGINS & SKILLS',
    source: 'antigravity-system/installed_plugins.md',
    extra: 'skills_reference.md',
    note: 'antigravity-system/installed_plugins.md & skills_reference.md'
  }
];

function readFile(filePath) {
  const full = path.join(ROOT, filePath);
  if (!fs.existsSync(full)) {
    console.warn(`  ⚠ Missing: ${filePath}`);
    return `*(File not found: ${filePath})*\n`;
  }
  return fs.readFileSync(full, 'utf8').trim();
}

function buildBundle() {
  console.log('🔄 Generating context_bundle.md...\n');

  let output = '';

  // Header
  output += `# NIMROD'S ANTIGRAVITY CONTEXT BUNDLE\n\n`;
  output += `> Auto-generated by \`generate_bundle.js\` on ${NOW}. Do not edit manually.\n`;
  output += `> Upload this file to your Claude Project to give Claude full context of Nimrod's PC environment.\n\n`;
  output += `---\n\n`;

  // Table of contents
  output += `## Contents\n\n`;
  SECTIONS.forEach(s => {
    output += `${s.num}. [${s.title}](#section-${s.num})\n`;
  });
  output += `\n---\n---\n\n`;

  // Sections
  for (const section of SECTIONS) {
    console.log(`  ✅ Section ${section.num}: ${section.title}`);

    output += `# SECTION ${section.num} — ${section.title}\n`;
    output += `*(From: ${section.note})*\n\n`;
    output += `---\n\n`;

    // Primary source
    output += readFile(section.source);
    output += `\n\n`;

    // Optional extra file appended
    if (section.extra) {
      output += readFile(section.extra);
      output += `\n\n`;
    }

    output += `---\n---\n\n`;
  }

  // Footer
  output += `---\n\n`;
  output += `*End of context bundle. Generated: ${NOW}*\n`;

  fs.writeFileSync(OUTPUT, output, 'utf8');

  const sizeKB = (fs.statSync(OUTPUT).size / 1024).toFixed(1);
  console.log(`\n✅ context_bundle.md generated — ${sizeKB} KB`);
  console.log(`📁 Location: ${OUTPUT}`);
  console.log(`\n📌 Next step: Upload context_bundle.md to your Claude Project files.`);
}

buildBundle();
